--- a/src/sanitize-svg.js
+++ b/src/sanitize-svg.js
@@ -0,0 +1,57 @@
+/**
+ * Sanitize a parsed SVG document to remove potentially malicious content
+ * that could lead to DOM-based cross-site scripting (XSS).
+ *
+ * This removes <script> elements, event-handler attributes (on*), and
+ * javascript: URIs from href/xlink:href attributes.
+ * @param {string} rawSvgText The raw SVG string read from an sb3 (or other) asset.
+ * @return {string} The sanitized SVG string.
+ */
+const sanitizeSvg = function (rawSvgText) {
+    // Strip <script>...</script> blocks (including their contents).
+    let svgText = rawSvgText.replace(
+        /<script[\s\S]*?<\/script\s*>/gi,
+        ''
+    );
+    // Strip self-closing or empty script tags.
+    svgText = svgText.replace(/<script[\s\S]*?\/?>/gi, '');
+
+    // Remove event-handler attributes such as onload, onclick, etc.
+    // Matches: onSomething = "..."  or  onSomething = '...'  or  onSomething=value
+    svgText = svgText.replace(
+        /\son\w+\s*=\s*("[^"]*"|'[^']*'|[^\s>]+)/gi,
+        ''
+    );
+
+    // Neutralize javascript: (and similar) URIs inside href / xlink:href.
+    svgText = svgText.replace(
+        /((?:xlink:)?href)\s*=\s*("|')\s*javascript:[^"']*\2/gi,
+        '$1=$2$2'
+    );
+    // Also handle unquoted javascript: URIs.
+    svgText = svgText.replace(
+        /((?:xlink:)?href)\s*=\s*javascript:[^\s>]*/gi,
+        '$1=""'
+    );
+
+    return svgText;
+};
+
+module.exports = sanitizeSvg;
