+        if id.miscselect_mask.len() != 4 || id.miscselect.len() != 4 {
+            bail!("Invalid QE Identity miscselect");
+        }
+        let report_misc = qe_report.misc_select.to_le_bytes();
+        for i in 0..4 {
+            if (report_misc[i] & id.miscselect_mask[i]) != id.miscselect[i] {
+                bail!("QE Report miscselect mismatch");
+            }
+        }
+
+        // ATTRIBUTES: (report.attributes & mask) == identity.attributes
+        if id.attributes_mask.len() != 16 || id.attributes.len() != 16 {
+            bail!("Invalid QE Identity attributes");
+        }
+        for i in 0..16 {
+            if (qe_report.attributes[i] & id.attributes_mask[i]) != id.attributes[i] {
