+        // ISVSVN must satisfy a non-revoked TCB level.
+        let mut matched = false;
+        for level in &id.tcb_levels {
+            if qe_report.isv_svn >= level.tcb.isvsvn {
+                if level.tcb_status == "Revoked" {
+                    bail!("QE TCB level revoked");
+                }
+                matched = true;
+                break;
+            }
+        }
+        if !matched {
+            bail!("QE Report isvsvn is below the lowest known TCB level");
+        }
+
+        Ok(())
+    }
